  const zeroScore = recs.some(function (rec) { return !(Number(rec.score) > 0); });

  target.innerHTML =
    '<p class="hint">Method <strong>' + hw6EscapeHtml(method) + "</strong>, alpha <strong>" + hw6Fmt(alpha, 2) +
