    return;
  }
  const outcome = hw6CurrentRecommendations();
  if (outcome.error) {
    target.innerHTML = hw6UnavailableHtml("Recommendations", outcome.error);
    return;
  }
  const recs = outcome.recs;
  if (!recs || recs.length === 0) {
