'use strict';

// Export the exact per-user split used by the browser application.
// Usage: node week6/prepare_data.cjs (paths are relative to this script).
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const source = name => path.join(__dirname, name);
const outputDir = source('data');
const itemBytes = fs.readFileSync(source('u.item'));
const ratingBytes = fs.readFileSync(source('u.data'));

// data.js is a classic browser script. Reuse its parsers and splitter without
// a DOM, fetching data, building a rating matrix, or duplicating split rules.
const context = vm.createContext({});
vm.runInContext(fs.readFileSync(source('data.js'), 'utf8'), context, {
    filename: 'data.js'
});
context.parseItemData(itemBytes.toString('latin1'));
context.parseRatingData(ratingBytes.toString('utf8'));
const split = context.splitByTimestamp();
const { movies, ratings, exclusions } = vm.runInContext(
    '({ movies, ratings, exclusions: SPLIT_EXCLUSIONS })', context
);

const movieIds = new Set(movies.map(movie => movie.id));
assert.equal(movieIds.size, movies.length, 'Movie IDs must be unique');
const key = row => `${row.userId}:${row.movieId}`;
const inputKeys = new Set(ratings.map(key));
assert.equal(inputKeys.size, ratings.length, 'Duplicate user/movie ratings');
for (const row of ratings) {
    assert([row.userId, row.movieId, row.rating, row.timestamp].every(Number.isFinite));
    assert(movieIds.has(row.movieId), `Missing metadata for movie ${row.movieId}`);
}

const seen = new Set();
const counts = {};
const timeRanges = {};
const tsvFiles = {};
for (const [name, rows] of Object.entries(split)) {
    // Membership is determined per user. Sorting each output globally makes
    // the saved files easy to inspect; it does not change that membership.
    rows.sort((a, b) => a.timestamp - b.timestamp ||
        a.userId - b.userId || a.movieId - b.movieId);
    for (const row of rows) {
        assert(inputKeys.has(key(row)), 'Unexpected rating in split');
        assert(!seen.has(key(row)), 'Rating appears in multiple splits');
        seen.add(key(row));
    }
    counts[name] = rows.length;
    timeRanges[name] = rows.length ? {
        min_timestamp: rows[0].timestamp,
        max_timestamp: rows[rows.length - 1].timestamp
    } : null;
    tsvFiles[name] = 'user_id\tmovie_id\trating\ttimestamp\n' + rows.map(row =>
        [row.userId, row.movieId, row.rating, row.timestamp].join('\t')
    ).join('\n') + (rows.length ? '\n' : '');
}
assert.equal(seen.size + exclusions.reduce((n, user) => n + user.count, 0), ratings.length);

const sha256 = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const summary = {
    protocol: 'per-user chronological 80/10/10',
    order_within_user: ['timestamp ascending', 'movie_id ascending for ties'],
    counts_per_user: 'train=floor(0.8*n), val=floor(0.1*n), test=remainder',
    output_order: ['timestamp ascending', 'user_id ascending', 'movie_id ascending'],
    minimum_ratings_per_user: 5,
    excluded_users: exclusions,
    users: new Set(ratings.map(row => row.userId)).size,
    movies: movies.length,
    ratings: ratings.length,
    counts,
    time_ranges: timeRanges,
    metadata: { file: '../u.item', encoding: 'latin1', join_key: 'movie_id' },
    source_sha256: { 'u.data': sha256(ratingBytes), 'u.item': sha256(itemBytes) },
    limitation: 'Chronological within each user; timestamps can overlap across splits. Equal timestamps use movie ID as a deterministic tie-break, not a known event order.'
};

fs.mkdirSync(outputDir, { recursive: true });
for (const [name, text] of Object.entries(tsvFiles)) {
    fs.writeFileSync(path.join(outputDir, `${name}.tsv`), text, 'utf8');
}
fs.writeFileSync(path.join(outputDir, 'split_summary.json'), JSON.stringify(summary, null, 2) + '\n');
console.log(JSON.stringify({ users: summary.users, movies: summary.movies,
    ratings: summary.ratings, counts, excluded_users: exclusions.length }, null, 2));
"}}

