    if (HW6_MF_MODEL.userFactors) HW6_MF_MODEL.userFactors.dispose();
    if (HW6_MF_MODEL.itemFactors) HW6_MF_MODEL.itemFactors.dispose();
  } catch (error) {
    // Disposal is best-effort; the reference is replaced wholesale below.
