    hw6RenderDatasetSummary();
    hw6RenderGraphSummary();
    hw6WireControls();
    HW6_STATE.loaded = true;
    hw6SetStatus(
      "Dataset ready: " + HW6_STATE.trainUserIds.length.toLocaleString("en-US") + " training users, " +
