assert.equal(graph.zeroDegreeUsers.length, graph.userIds.filter((id, u) => graph.degree[u] === 0).length);
assert.equal(graph.zeroDegreeMovies.length, graph.movieIds.filter((id, i) => graph.degree[graph.nUsers+i] === 0).length);
