assert.equal(graph.movieOfNode(0), -1);
assert.equal(graph.movieOfNode(graph.nodeCount), -1);
assert.equal(graph.movieOfNode(graph.nUsers + 0.5), -1);
assert.equal(graph.isUserNode(-1), false);
assert.equal(graph.isUserNode(graph.nodeCount), false);
assert.equal(graph.isUserNode(0.5), false);
for (const movieNode of context.graphNeighbors(graph, 0)) {
  assert(context.graphNeighbors(graph, movieNode).includes(0));
}
context.testFirstUser = graph.userIds[0];
// Regression: the default 120-node cap must include movie nodes and edges.
const view = vm.runInContext('graphBuildEgoView(testFirstUser)', context);
assert.equal(view.nodes.length, 120);
assert(view.edges.length > 0);
assert(view.nodes.some(node => node.kind === 'movie'));
for (const node of view.nodes) {
