/* --- graph view --------------------------------------------------------- */

.graph-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.6rem;
}

.graph-view {
  display: block;
  width: 100%;
  max-width: 100%;
  height: 24rem;
  background: #ffffff;
  border: 1px solid var(--border);
  border-radius: 6px;
}

.graph-legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.9rem;
  margin-top: 0.6rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.legend-swatch {
  display: inline-block;
  width: 0.85rem;
  height: 0.85rem;
  border: 1px solid var(--border);
  border-radius: 3px;
  background: var(--inset);
}

.caption {
  color: var(--muted);
  font-size: 0.85rem;
  margin: 0.5rem 0 0;
}

/* --- tables, lists and log --------------------------------------------- */

.summary-list {
  display: grid;
  font-style: italic;
  margin: 0;
}

/* --- responsive --------------------------------------------------------- */

@media (max-width: 760px) {
  main {
    padding: 0.75rem;
  }

  .control-grid,
  .control-grid--two {
    grid-template-columns: 1fr;
  }

  .graph-view {
    height: 18rem;
  }
}
