 */
function hw6RunAlphaSweep() {
  const rows = [];
  let best = null;
  let bestRecall = -Infinity;
  let note = "";

  for (let i = 0; i < ALPHA_GRID.length; i++) {
    const alpha = ALPHA_GRID[i];
    const row = { alpha: alpha, recall: null, cohortSize: hw6SharedCohort("val").length, error: null };
    try {
