  let residual = Infinity;
  let converged = false;
  try {
    p = tensors.restart.clone();
    for (let k = 0; k < maxIter; k++) {
      const step = tf.tidy(() => {
        let incoming;
        if (explicit) {
          incoming = tf.matMul(tensors.links, p, true, false);
        } else {
