output.text:
 * have been disposed. Shared graph tensors live only until this call ends.
 * tf.nextFrame yields to the browser between batches, never inside tf.tidy.
 *
 * @param {number[]} userIds Raw training user IDs, in the requested result order.
 * @param {number} alpha Link-following probability in [0, 1].
 * @param {{graph?: Graph, batchSize?: number, tol?: number, maxIter?: number,
 *   onBatch?: function(Object[], number, number): (void|Promise<void>)}} [opts]
 *   batchSize defaults to 32; allowed integer range is 1..128. Defaults for tol
 *   and maxIter are 1e-6 and 500. An empty userIds array returns [].
 * @returns {Promise<Array<{userId: number, p: Float64Array, iterations: number,
 *   residual: number, converged: boolean}>>}
 */
async function personalizedPageRankBatch(userIds, alpha, opts) {
  if (opts !== undefined && (opts === null || typeof opts !== "object" || Array.isArray(opts))) {
    throw new TypeError("PPR batch options must be an object.");
  }
  const options = opts || {};
  const tol = options.tol === undefined ? 1e-6 : options.tol;
  const maxIter = options.maxIter === undefined ? 500 : options.maxIter;
  const batchSize = options.batchSize === undefined ? 32 : options.batchSize;
  if (!Number.isFinite(alpha) || alpha < 0 || alpha > 1) {
    throw new RangeError("alpha must be a finite link-following probability in [0, 1].");
  }
  if (!Number.isFinite(tol) || tol <= 0 || !Number.isInteger(maxIter) || maxIter < 1) {
    throw new RangeError("tol must be positive and maxIter must be a positive integer.");
  }
  if (!Number.isInteger(batchSize) || batchSize < 1 || batchSize > 128) {
    throw new RangeError("PPR batchSize must be an integer from 1 to 128.");
  }
  if (options.onBatch !== undefined && typeof options.onBatch !== "function") {
    throw new TypeError("PPR batch onBatch must be a function.");
  }
  if (!Array.isArray(userIds)) throw new TypeError("PPR batch userIds must be an array of raw user IDs.");
  // Snapshot caller-owned arrays before the first await; a progress callback
  // cannot change which users are requested midway through the calculation.
  const ids = userIds.slice();
  if (!ids.length) return [];
  const graph = options.graph === undefined ? GRAPH : options.graph;
  if (!graph || typeof graph.nodeOfUser !== "function") {
    throw new Error("Build a training graph or supply opts.graph before running batched PPR.");
  }
  const normalized = rowNormalize(graph);
  const n = graph.nUsers + graph.nMovies;
  if (!n) throw new Error("Batched PPR requires at least one graph node.");
  const nodes = ids.map(userId => {
    const node = Number.isSafeInteger(userId) ? graph.nodeOfUser(userId) : -1;
    if (!Number.isInteger(node) || node < 0 || node >= graph.nUsers) {
      throw new RangeError("Unknown or invalid raw restart user ID: " + String(userId));
    }
    return node;
  });
  if (typeof tf === "undefined" || !tf.getBackend()) {
    throw new Error("TensorFlow.js must be ready before running batched PPR.");
  }

  let shared = null;
  const results = [];
  try {
    shared = tf.tidy(() => ({
      links: tf.tensor2d(graph.R, [graph.nUsers, graph.nMovies]),
      inverse: tf.tensor2d(Float32Array.from(normalized.inverseDegree), [n, 1]),
      dangling: tf.tensor2d(Float32Array.from(normalized.danglingMask, value => value ? 1 : 0), [n, 1])
    }));
    for (let start = 0; start < ids.length; start += batchSize) {
      const width = Math.min(batchSize, ids.length - start);
      const restartValues = new Float32Array(n * width);
      for (let col = 0; col < width; col++) restartValues[nodes[start + col] * width + col] = 1;
      const active = new Float32Array(width).fill(1);
      const residuals = new Float64Array(width).fill(Infinity);
      const iterations = new Uint32Array(width);
      const converged = new Array(width).fill(false);
      let remaining = width;
      let restart = null;
      let p = null;
      let batchResults;
      try {
        restart = tf.tensor2d(restartValues, [n, width]);
        p = restart.clone();
        for (let k = 0; k < maxIter && remaining > 0; k++) {
          const step = tf.tidy(() => {
            const weighted = p.mul(shared.inverse);
            const userMass = weighted.slice([0, 0], [graph.nUsers, width]);
            const movieMass = weighted.slice([graph.nUsers, 0], [graph.nMovies, width]);
            const incoming = tf.concat([
              tf.matMul(shared.links, movieMass),
              tf.matMul(shared.links, userMass, true, false)
            ], 0);
            // Sum over nodes independently for each restart column. A dangling
            // user's mass consequently returns to that same user, not a peer.
            const restartWeight = p.mul(shared.dangling).sum(0, true).mul(alpha).add(1 - alpha);
            const candidate = incoming.mul(alpha).add(restart.mul(restartWeight));
            const activeColumns = tf.tensor2d(active, [1, width]);
            const next = candidate.mul(activeColumns).add(p.mul(tf.onesLike(activeColumns).sub(activeColumns)));
            return { next, residual: next.sub(p).abs().sum(0) };
          });
          p.dispose();
          p = step.next;
          let differences;
          try {
            differences = await step.residual.data();
          } finally {
            step.residual.dispose();
          }
          for (let col = 0; col < width; col++) {
            if (!active[col]) continue;
            const residual = differences[col];
            if (!Number.isFinite(residual)) throw new Error("Batched PPR produced a non-finite residual.");
            residuals[col] = residual;
            iterations[col] = k + 1;
            if (residual < tol) {
              converged[col] = true;
              active[col] = 0;
              remaining--;
            }
          }
        }
        const values = await p.data();
        batchResults = Array.from({ length: width }, (_, col) => {
          const probabilities = new Float64Array(n);
          for (let node = 0; node < n; node++) probabilities[node] = values[node * width + col];
          return {
            userId: ids[start + col], p: probabilities,
            iterations: iterations[col], residual: residuals[col], converged: converged[col]
          };
        });
      } finally {
        if (p) p.dispose();
        if (restart) restart.dispose();
      }
      results.push(...batchResults);
      if (options.onBatch) await options.onBatch(batchResults, results.length, ids.length);
      if (start + width < ids.length) await tf.nextFrame();
    }
    return results;
  } finally {
    if (shared) for (const tensor of Object.values(shared)) tensor.dispose();
  }
}

/**
 * Shared synchronous TensorFlow.js iteration for global and personal restart.
 *
 * The browser's existing scoring and test interfaces are synchronous, so only
 * the scalar residual and final vector use dataSync(). All probability
 * propagation is batched tensor math. Per-step temporaries are scoped by tidy;
 * all surviving tensors are disposed even when a calculation fails.
      error: null,
      note: null,
    };
    try {
      if (method === "mf" && !mfReady) {
        // Never report a silent 0: state plainly that the reference is untrained.
        row.note = "MF not trained yet \u2014 its recall is not meaningful.";
      } else {
        if (method === "ppr") await hw6PreparePprProfiles(cohort, alpha, "Test PPR");
        const report = recallAtK(method, HW6_K, name);
        row.recall = Number(report.recall);
        if (Array.isArray(report.cohort)) row.cohortSize = report.cohort.length;
        if (Number.isFinite(Number(report.excludedUnseen))) row.excludedUnseen = Number(report.excludedUnseen);
        if (Number.isFinite(Number(report.excludedNoEligible))) row.excludedNoEligible = Number(report.excludedNoEligible);
        row.meanPopularity = hw6MeanListPopularityForCohort(method, cohort, name, alpha);
        const record = usesAlpha ? HW6_STATE.convergence[method === "ppr" ? "ppr" : "pagerank"] : null;
        if (record) {
          row.iterations = record.iterations;
          row.residual = record.residual;
          row.converged = hw6ConvergenceVerdict(record).value;
        }
      }
    } catch (error) {
      row.error = String(error && error.message ? error.message : error);
    }
    rows.push(row);
  }

  HW6_STATE.comparisonRows = rows;
  return rows;
}

/**
 * Mean over the cohort of each user's recommended-list mean popularity.
 *
 * @param {string} method
 * @param {number[]} cohort
 * @param {"test"|"val"} split
 * @param {number} alpha
 * @returns {number|null} `null` when no list could be produced.
 */
function hw6MeanListPopularityForCohort(method, cohort, split, alpha) {
  let total = 0;
  let users = 0;
  for (let i = 0; i < cohort.length; i++) {
    const recs = recommendTopK(method, cohort[i], HW6_K, split);
    const mean = hw6MeanPopularity(recs);
    if (mean === null) continue;
    total += mean;
    users++;
  }
  return users > 0 ? total / users : null;
}

/**
 * Validation-only alpha sweep for PPR (readme section 6.1).
 *
 * Recall@10 is measured on the validation split for each alpha in `ALPHA_GRID`.
 * The selected alpha maximises validation recall; exact ties are broken toward
 * the SMALLER alpha. Test outcomes are never consulted here.
 *
 * @returns {Promise<{rows:Array<Object>, best:(number|null), note:string}>}
 */
async function hw6RunAlphaSweep() {
  if (!HW6_STATE.splitReady) throw new Error("Wait for the dataset to finish loading.");
  if (!hw6ActiveGraph()) hw6HandleBuildGraph();
  if (!hw6ActiveGraph()) throw new Error("Build the training graph before running the alpha sweep.");
  const rows = [];
  const cohort = hw6SharedCohort("val");
  if (!cohort.length) throw new Error("The validation cohort has no eligible relevant movies.");
  let best = null;
  let bestRecall = -Infinity;
  let note = "";

  for (let i = 0; i < ALPHA_GRID.length; i++) {
    const alpha = ALPHA_GRID[i];
    const row = { alpha: alpha, recall: null, cohortSize: cohort.length, error: null };
    try {
      const profiles = await hw6PreparePprProfiles(cohort, alpha, "Validation alpha " + alpha.toFixed(2));
      const report = hw6WithAlpha(alpha, function () { return recallAtK("ppr", HW6_K, "val"); });
      row.recall = Number(report.recall);
      row.excludedUnseen = report.excludedUnseen;
      row.excludedNoEligible = report.excludedNoEligible;
      row.unseenIds = hw6CohortExclusions("val").unseenIds;
      row.iterations = Math.max(...cohort.map(userId => profiles.results.get(userId).iterations));
      row.residual = Math.max(...cohort.map(userId => profiles.results.get(userId).residual));
      row.converged = cohort.every(userId => profiles.results.get(userId).converged);
      if (Array.isArray(report.cohort)) row.cohortSize = report.cohort.length;
      if (Number.isFinite(row.recall) && (row.recall > bestRecall || (row.recall === bestRecall && alpha < best))) {
        bestRecall = row.recall;
        best = alpha;
      }
    } catch (error) {
      row.error = String(error && error.message ? error.message : error);
      note = row.error;
    }
    rows.push(row);
    HW6_STATE.alphaSweepRows = rows;
    hw6RenderAlphaSweep({ rows: rows, best: null, note: note, running: true });
    if (typeof tf.nextFrame === "function") await tf.nextFrame();
  }

  if (rows.some(row => row.error)) best = null;
  HW6_STATE.alphaSweepRows = rows;
  HW6_STATE.alphaSweepBest = best;
  HW6_STATE.alphaSweepNote = note;
  if (best !== null) {
    hw6SetAlpha(best);
    HW6_STATE.convergence.pagerank = null;
    HW6_STATE.convergence.ppr = null;
    hw6RenderConvergence();
    hw6SafeRenderGraphView({ colorBy: GRAPH_VIEW_STATE.colorBy });
  }
  return { rows: rows, best: best, note: note };
}

/** Verify batched PPR against the synchronous implementation on a tiny graph. */
async function hw6VerifyBatchedPpr() {
  if (HW6_STATE.batchVerification) return;
  const graph = buildGraph([
    { userId: 7, movieId: 1, rating: 5 },
    { userId: 7, movieId: 2, rating: 4 },
    { userId: 42, movieId: 3, rating: 3 },
    { userId: 99, movieId: 2, rating: 5 }
  ]);
  const before = tf.memory().numTensors;
  for (const alpha of [0, 0.5, 0.85, 0.95]) {
    const results = await personalizedPageRankBatch([7, 42, 99], alpha, { graph: graph, batchSize: 2 });
    for (const result of results) {
      const single = hw6AdapterPPR(graph, graph.nodeOfUser(result.userId), alpha, result.userId);
      let mass = 0;
      let error = 0;
      for (let i = 0; i < result.p.length; i++) {
        mass += result.p[i];
        error += Math.abs(result.p[i] - single.scores[i]);
      }
      if (error > 1e-5 || Math.abs(mass - 1) > 1e-5 || !result.converged || result.residual >= HW6_TOLERANCE) {
        throw new Error("Batched PPR verification failed for user " + result.userId + ", alpha " + alpha);
      }
    }
  }
  if (tf.memory().numTensors !== before) throw new Error("Batched PPR retained tensors after completion.");
  HW6_STATE.batchVerification = "12 user/alpha cases agree with single-user PPR; isolated seeds preserve mass; no retained tensors";
}

/** Prepare training-only PPR profiles once per alpha; relevance is evaluated separately. */
async function hw6PreparePprProfiles(userIds, alpha, label) {
  const graph = hw6ActiveGraph();
  if (!graph) throw new Error("Build the training graph first.");
  await hw6VerifyBatchedPpr();
  let profiles = HW6_STATE.pprProfiles.get(alpha);
  if (!profiles || profiles.graph !== graph) {
    profiles = { graph: graph, results: new Map() };
    HW6_STATE.pprProfiles.set(alpha, profiles);
  }
  const missing = userIds.filter(userId => !profiles.results.has(userId));
  await personalizedPageRankBatch(missing, alpha, {
    graph: graph,
    batchSize: 32,
    async onBatch(results, completed, total) {
      for (const result of results) {
        if (!result.converged) throw new Error("PPR did not converge for user " + result.userId + " at alpha " + alpha);
        profiles.results.set(result.userId, result);
      }
      hw6SetStatus(label + ": " + completed + "/" + total + " users computed.");
    }
  });
  return profiles;
}

