function recallAtK(method, K, split) {
  if (!["popularity", "pagerank", "ppr", "mf"].includes(method)) throw new RangeError("Unknown recommendation method: " + method);
  const name = split === "val" ? "val" : "test";
  const limit = K === undefined ? 10 : Number(K);
  if (!Number.isFinite(limit)) throw new RangeError("K must be finite.");
  const cohort = hw6SharedCohort(name);
  const exclusions = hw6CohortExclusions(name);
  const perUser = [];
  let sum = 0;
