function hw6RunAndRecordConvergence(kind, graph, alpha, userId) {
  const result = kind === "ppr" ? hw6RunPPR(graph, userId, alpha) : hw6RunPageRank(graph, alpha);
  HW6_STATE.convergence[kind] = {
