  HW6_STATE.batchVerification = "12 user/alpha cases agree with single-user PPR; isolated seeds preserve mass; no retained tensors; " +
    cappedCases + " capped fixture cases correctly reported as nonconverged";
}

/** Prepare training-only PPR profiles once per alpha; relevance is evaluated separately. */
async function hw6PreparePprProfiles(userIds, alpha, label) {
  const graph = hw6ActiveGraph();
  if (!graph) throw new Error("Build the training graph first.");
  await hw6VerifyBatchedPpr();
  let profiles = HW6_STATE.pprProfiles.get(alpha);
  if (!profiles || profiles.graph !== graph) {
    profiles = { graph: graph, results: new Map() };
    HW6_STATE.pprProfiles.set(alpha, profiles);
