  try {
    if (method === "pagerank") return Float64Array.from(hw6RunPageRank(graph, alpha).scores);
    if (method === "ppr") return Float64Array.from(hw6RunPPR(graph, seedUserId, alpha).scores);
    const vector = new Float64Array(n);
