    const index = hw6MovieNodeIndex(graph);
    if (method === "popularity") {
      index.forEach(function (node, movieId) { vector[node] = hw6PopularityOf(movieId); });
      return vector;
    }
    const scored = mfScores(seedUserId);
    index.forEach(function (node, movieId) {
