 * only PPR state; global PageRank and the independent recommendation target
 * are unaffected. Graph users outside the test cohort can still be PPR seeds.
 *
 * @param {number} userId Raw training user ID.
 * @returns {void}
 */
function hw6SelectGraphUser(userId) {
  const graph = hw6ActiveGraph();
  if (!graph || !Number.isFinite(userId) || graph.nodeOfUser(userId) < 0) {
    hw6SetStatus("Select a training user and build the graph first.");
    return;
  }
  const state = typeof GRAPH_VIEW_STATE !== "undefined" ? GRAPH_VIEW_STATE : null;
  const colorBy = state ? state.colorBy : "score";
  const select = document.getElementById("seed-user-select");
  if (select) {
    if (!Array.from(select.options).some(option => option.value === String(userId))) {
      const option = document.createElement("option");
      option.value = String(userId);
      option.textContent = "User " + userId + " (outside evaluation cohort)";
      select.appendChild(option);
    }
    select.value = String(userId);
  }
  if (state && state.mode === "ego" && state.seedUserId === userId) return;
  HW6_STATE.ppr = null;
  HW6_STATE.convergence.ppr = null;
  if (hw6ReadMethod() === "ppr") {
    try {
      hw6RunAndRecordConvergence("ppr", graph, hw6ReadAlpha(), userId);
    } catch (error) {
      hw6SetStatus("PPR unavailable: " + String(error && error.message ? error.message : error));
      return;
    }
  }
  hw6SafeRenderGraphView({ colorBy: colorBy });
  hw6RenderConvergence();
  hw6SetStatus("Restart user set to " + userId + "; graph refreshed" +
    (hw6ReadMethod() === "ppr" ? " with this user's PPR scores." : "."));
}

