/**
 * Render the convergence panel (readme section 3.4) into `#convergence-results`.
 *
 * Reports iterations, the final L1 residual and whether convergence was reached
 * for global PageRank and PPR. Never claims convergence when the iteration cap
 * was hit. The four-node teaching example has its own calculation panel.
 *
 * @returns {void}
 */
function hw6RenderConvergence() {
  const target = document.getElementById("convergence-results");
  if (!target) return;
  const rows = [];

  const keys = ["pagerank", "ppr"];
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const record = HW6_STATE.convergence[key];
    if (!record) {
      rows.push("<tr><td>" + (key === "ppr" ? "PPR" : "global PageRank") + "</td><td colspan=\"5\">not run yet</td></tr>");
      continue;
    }
    const verdict = hw6ConvergenceVerdict(record);
    const convergedText =
      verdict.value === null
        ? "not reported"
        : verdict.value
          ? "yes" + (verdict.derived ? " (derived from residual)" : "")
          : "no \u2014 cap or tolerance not met" + (verdict.derived ? " (derived)" : "");
    rows.push(
      "<tr>" +
      "<td>" + (key === "ppr" ? "PPR (user " + record.userId + ")" : "global PageRank") + "</td>" +
      '<td class="num">' + hw6Fmt(record.alpha, 2) + "</td>" +
      '<td class="num">' + (record.iterations === null ? "\u2014" : record.iterations) + "</td>" +
      '<td class="num">' + (record.residual === null ? "\u2014" : hw6Fmt(record.residual, 10)) + "</td>" +
      "<td>" + convergedText + "</td>" +
      '<td class="num">' + (record.iterations === null ? "\u2014" : record.iterations + " / " + HW6_MAX_ITERATIONS) + "</td>" +
      "</tr>",
    );
  }

  target.innerHTML =
    '<table class="data-table">' +
    "<thead><tr><th scope=\"col\">Run</th><th scope=\"col\">Alpha</th><th scope=\"col\">Iterations</th>" +
    "<th scope=\"col\">Final L1 residual</th><th scope=\"col\">Converged</th><th scope=\"col\">Cap</th></tr></thead>" +
    "<tbody>" + rows.join("") + "</tbody></table>" +
    '<p class="hint">Tolerance ' + HW6_TOLERANCE + ", cap " + HW6_MAX_ITERATIONS +
    " iterations. Reaching the cap is not proof of convergence. PageRank is an iterative calculation, not neural-network training.</p>";
}

/**
 * Render the alpha sweep panel (readme section 6.1).
 *
 * @param {{rows:Array<Object>, best:(number|null), note:string}} [sweep]
 * @returns {void}
 */
function hw6RenderAlphaSweep(sweep) {
  const target = document.getElementById("alpha-sweep-results");
  if (!target) return;
  const data = sweep || { rows: HW6_STATE.alphaSweepRows, best: HW6_STATE.alphaSweepBest, note: HW6_STATE.alphaSweepNote || "" };
  if (!data || !data.rows || data.rows.length === 0) {
    target.innerHTML =
      '<p class="empty-state">Validation Recall@10 for alpha in {0.50, 0.70, 0.85, 0.95} is reported here; ' +
      "exact ties are broken by the smaller alpha.</p>";
    return;
  }
  const failed = data.rows.some(function (row) { return !!row.error; });
  if (failed) {
    const first = data.rows.find(function (row) { return !!row.error; });
    target.innerHTML = hw6UnavailableHtml("Alpha sweep", first.error);
    return;
  }

  const body = data.rows
    .map(function (row) {
      const isBest = data.best !== null && Math.abs(row.alpha - data.best) < 1e-12;
      return (
        "<tr" + (isBest ? ' class="best-row"' : "") + ">" +
        '<td class="num">' + hw6Fmt(row.alpha, 2) + "</td>" +
        '<td class="num">' + hw6Fmt(row.recall) + "</td>" +
        '<td class="num">' + row.cohortSize.toLocaleString("en-US") + "</td>" +
        '<td class="num">' + row.iterations + "</td>" +
        "<td>" + (row.converged ? "yes" : "no") + "</td>" +
        "<td>" + (isBest ? "selected (validation)" : "") + "</td>" +
        "</tr>"
      );
    })
    .join("");

  target.innerHTML =
    '<table class="data-table">' +
    "<thead><tr><th scope=\"col\">Alpha</th><th scope=\"col\">Validation Recall@10</th>" +
// Fixture teaching demo (public: fixtureStep / fixtureReset)
//
// THIS DEMO EXISTS ONLY FOR THE 4-NODE FIXTURE. It is a tiny plain-JavaScript
// propagation so the animation works before you write any stub, and it is NOT a
// template for the MovieLens implementation. The MovieLens propagation must use
// TensorFlow.js tensor operations on R and R-transpose (readme.md section 3.5),
// as required by pageRank / personalizedPageRank.
// ---------------------------------------------------------------------------

/**
 * Update the fixture's own calculation panel with its iteration and residual.
 *
 * @returns {void}
 */
function graphRenderConvergence() {
  const target = document.getElementById("fixture-convergence-results");
  if (!target) return;
  const fixture = GRAPH_VIEW_STATE.fixture;
  const p = fixture.p || [];
  const values = p
    .map((value, i) => REFERENCE_GRAPH.nodeOrder[i] + " " + Number(value).toFixed(10))
    .join(", ");
  const residual = fixture.residual === null ? "-" : Number(fixture.residual).toExponential(3);

  target.innerHTML =
    "<p><strong>Fixture demo (4-node reference graph)</strong> - iteration " +
    fixture.iteration +
    ", alpha " +
    Number(fixture.alpha !== undefined ? fixture.alpha : graphReadAlpha()).toFixed(2) +
    ", restart " +
    graphEscape(fixture.restart || "uniform") +
    ".</p>" +
    '<dl class="summary-list">' +
    "<dt>L1 residual (last step)</dt><dd>" + graphEscape(residual) + "</dd>" +
    "<dt>Current p</dt><dd>" + graphEscape(values) + "</dd>" +
    "</dl>" +
    '<p class="hint">This plain-JavaScript demo exists only for the 4-node fixture and is not a ' +
    "template for the MovieLens implementation, which must use TensorFlow.js tensor operations " +
    "on R and R-transpose (readme.md section 3.5).</p>";
}

/**
 * Advance the 4-node fixture demo by one propagation step and redraw it.
 *
 * @returns {void}
 */
function fixtureStep() {
  const fixture = GRAPH_VIEW_STATE.fixture;
  const alpha = graphReadAlpha();
  if (!fixture.p) {
    fixture.p = graphFixtureRestartVector(fixture.restart || "uniform");
    fixture.iteration = 0;
  }
  const result = graphFixturePropagate(alpha, fixture.restart || "uniform", fixture.p);
  fixture.p = result.p;
  fixture.iteration += 1;
  fixture.residual = result.residual;
  fixture.alpha = alpha;
  renderGraphView({ mode: "fixture" });
  graphRenderConvergence();
}

/**
 * Reset the fixture demo to iteration 0 (the restart distribution) and redraw.
 *
 * @returns {void}
 */
function fixtureReset() {
  const fixture = GRAPH_VIEW_STATE.fixture;
  fixture.alpha = graphReadAlpha();
  fixture.iteration = 0;
  fixture.p = graphFixtureRestartVector(fixture.restart || "uniform");
  fixture.residual = null;
  const restartSelect = document.getElementById("fixture-restart");
  if (restartSelect) restartSelect.value = fixture.restart;
  renderGraphView({ mode: "fixture" });
  graphRenderConvergence();
}

// ---------------------------------------------------------------------------
// Bootstrap (private)
// ---------------------------------------------------------------------------

/** Redraw visible canvases after a tab or width change, preserving their scores. */
function graphRedrawVisibleViews() {
}

// ---------------------------------------------------------------------------
// UI wiring (provided)
// ---------------------------------------------------------------------------

/** Hover, keyboard and touch help for labels in the Controls panel. */
function hw6WireControlHelp() {
  let active = null;
  let pinned = null;
  const close = function () {
    if (active) {
      document.getElementById(active.getAttribute("aria-controls")).hidden = true;
      active.setAttribute("aria-expanded", "false");
    }
    active = null;
    pinned = null;
  };
  const show = function (button) {
    if (active && active !== button) close();
    active = button;
    document.getElementById(button.getAttribute("aria-controls")).hidden = false;
    button.setAttribute("aria-expanded", "true");
  };
  document.querySelectorAll(".control-help-button").forEach(button => {
    button.addEventListener("mouseenter", () => show(button));
    button.addEventListener("focus", () => show(button));
    button.addEventListener("blur", () => { if (active === button) close(); });
    button.closest(".control-label").addEventListener("mouseleave", () => {
      if (active === button && pinned !== button && document.activeElement !== button) close();
    });
    button.addEventListener("click", () => {
      const wasPinned = pinned === button;
      close();
      if (!wasPinned) {
        show(button);
        pinned = button;
      }
    });
  });
  document.addEventListener("click", event => {
    if (!event.target.closest(".control-label")) close();
  });
  document.addEventListener("keydown", event => {
    if (event.key === "Escape" && active) {
      event.preventDefault();
      close();
    }
  });
}

/** Switch workspaces without discarding recommendations or fixture progress. */
function hw6ShowWorkspace(tabId, focusTab) {
  document.querySelectorAll('[role="tab"][aria-controls]').forEach(tab => {
    const active = tab.id === tabId;
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = active ? 0 : -1;
    const panel = document.getElementById(tab.getAttribute("aria-controls"));
    if (panel) panel.hidden = !active;
    if (active && focusTab) tab.focus();
  });
  if (typeof graphHideTooltip === "function") graphHideTooltip();
  if (typeof graphRedrawVisibleViews === "function") graphRedrawVisibleViews();
  const activeTab = document.getElementById(tabId);
  if (activeTab) {
    const panel = document.getElementById(activeTab.getAttribute("aria-controls"));
    const tabBar = activeTab.closest('[role="tablist"]');
    const top = panel.getBoundingClientRect().top + window.scrollY - tabBar.offsetHeight - 20;
    window.scrollTo({ top: Math.max(0, top) });
  }
}

/** Standard click and keyboard navigation for the two app workspaces. */
function hw6WireWorkspaceTabs() {
  const tabs = Array.from(document.querySelectorAll('[role="tab"][aria-controls]'));
  tabs.forEach((tab, index) => {
    tab.addEventListener("click", () => hw6ShowWorkspace(tab.id, false));
    tab.addEventListener("keydown", event => {
      let next;
      if (event.key === "ArrowRight") next = (index + 1) % tabs.length;
      else if (event.key === "ArrowLeft") next = (index + tabs.length - 1) % tabs.length;
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = tabs.length - 1;
      else return;
      event.preventDefault();
      hw6ShowWorkspace(tabs[next].id, true);
    });
  });
}

/**
 * Wire every control once. Safe to call a single time from the bootstrap; all
 * lookups are null-guarded so a missing element cannot throw at load time.
 *
 * @returns {void}
        <h2 id="fixture-convergence-heading">Fixture calculation</h2>
        <div id="fixture-convergence-results" role="status" aria-live="polite"></div>
      </section>
    </div>
  </main>

  <footer class="site-footer">
    <p>LLM4Rec — Recommender Systems course, HSE University. Instructor: Seungmin Jin (sedzhin@hse.ru).</p>
    <p>The full assignment specification is in <code>readme.md</code> in this directory.</p>
  </footer>

  <script src="https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js"></script>
  <script src="vendor/d3.min.js"></script>
  <script src="data.js"></script>
  <script src="graph.js?v=20261020-workspaces-3"></script>
  <script src="script.js?v=20261020-control-help"></script>
</body>
</html>

