/** Highest raw movie id in the dataset; cached for factor allocation. */
let HW6_MAX_MOVIE_ID = 0;

/** Chronological 80/10/10 split, set once by the bootstrap. */
const HW6_SPLIT = { train: [], val: [], test: [] };

/** Mutable application state (all names prefixed so `graph.js` stays untouched). */
const HW6_STATE = {
  backend: null,
  loaded: false,
  splitReady: false,

  /** Sorted distinct movie ids observed in the training split (readme 5 candidate pool). */
  candidateIds: [],
  /** `Set` view of `candidateIds`. */
  candidateSet: new Set(),
  /** Sorted distinct user ids observed in the training split. */
  trainUserIds: [],
  /** `movieId -> count of distinct users with a positive (>= 4.0) training rating`. */
  popularity: new Map(),
  /** `userId -> Set(movieId)` per split; drives the previously-rated exclusion rules. */
  pairsBySplit: { train: new Map(), val: new Map(), test: new Map() },
  /** `userId -> Map(movieId -> rating)` per split; drives relevance. */
  gradesBySplit: { train: new Map(), val: new Map(), test: new Map() },
  /** Users with at least one positive training edge (readme 7.1). */
  usersWithPositiveTrain: new Set(),
  /** Count of distinct positive training (user, movie) pairs. */
  positivePairs: 0,

  /** Cached propagation results, keyed by alpha / seed. */
  pageRank: null,
  ppr: null,
  /** Convergence records for the panel: `{ pagerank, ppr }`. */
  convergence: { pagerank: null, ppr: null },

  /** Last runner outputs (also the exporters' sources). */
  comparisonRows: null,
  alphaSweepRows: null,
  alphaSweepBest: null,
  alphaSweepRunning: false,
  /** Raw-user PPR results by alpha, each tied to its training graph. */
  pprProfiles: new Map(),
  batchVerification: null,
  batchVerificationError: null,
  comparisonNote: null,
  alphaSweepNote: null,
  demo: null,
  recallReport: null,
  recommendationRows: [],
  /** `Set` of recommendation row keys already recorded, to avoid duplicate CSV rows. */
  recommendationKeys: new Set(),

  /** Last self-check run, reused by `serializeVerification()`. */
  lastVerification: null,
};

// ---------------------------------------------------------------------------
// Small helpers (provided)
// ---------------------------------------------------------------------------
 * Render the convergence panel (readme section 3.4) into `#convergence-results`.
 *
 * Reports iterations, the final L1 residual and whether convergence was reached
 * for global PageRank and PPR. Never claims convergence when the iteration cap
 * was hit. The study row mirrors the fixture's own alpha and manual progress.
 *
 * @returns {void}
 */
function hw6RenderConvergence() {
  const target = document.getElementById("convergence-results");
  if (!target) return;
  const rows = [];

  const fixture = typeof GRAPH_VIEW_STATE !== "undefined" ? GRAPH_VIEW_STATE.fixture : null;
  if (fixture) {
    const hasResidual = fixture.iteration > 0 && Number.isFinite(fixture.residual);
    rows.push(
      '<tr data-run="fixture">' +
      "<td>Study example (restart " + hw6EscapeHtml(fixture.restart) + ")</td>" +
      '<td class="num">' + hw6Fmt(fixture.alpha, 2) + "</td>" +
      '<td class="num">' + fixture.iteration + "</td>" +
      '<td class="num">' + (hasResidual ? hw6Fmt(fixture.residual, 10) : "\u2014") + "</td>" +
      "<td>" + (hasResidual ? (fixture.residual < HW6_TOLERANCE ? "yes" : "no") : "not run yet") + "</td>" +
      "<td>manual</td></tr>"
    );
  }

  const keys = ["pagerank", "ppr"];
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const record = HW6_STATE.convergence[key];
    if (!record) {
      rows.push("<tr><td>" + (key === "ppr" ? "PPR" : "global PageRank") + "</td><td colspan=\"5\">not run yet</td></tr>");
      continue;
    }
    const verdict = hw6ConvergenceVerdict(record);
    const convergedText =
      verdict.value === null
        ? "not reported"
        : verdict.value
          ? "yes" + (verdict.derived ? " (derived from residual)" : "")
          : "no \u2014 cap or tolerance not met" + (verdict.derived ? " (derived)" : "");
    rows.push(
      "<tr>" +
      "<td>" + (key === "ppr" ? "PPR (user " + record.userId + ")" : "global PageRank") + "</td>" +
      '<td class="num">' + hw6Fmt(record.alpha, 2) + "</td>" +
      '<td class="num">' + (record.iterations === null ? "\u2014" : record.iterations) + "</td>" +
      '<td class="num">' + (record.residual === null ? "\u2014" : hw6Fmt(record.residual, 10)) + "</td>" +
      "<td>" + convergedText + "</td>" +
      '<td class="num">' + (record.iterations === null ? "\u2014" : record.iterations + " / " + HW6_MAX_ITERATIONS) + "</td>" +
      "</tr>",
    );
  }

  target.innerHTML =
    '<table class="data-table">' +
    "<thead><tr><th scope=\"col\">Run</th><th scope=\"col\">Alpha</th><th scope=\"col\">Iterations</th>" +
    "<th scope=\"col\">Final L1 residual</th><th scope=\"col\">Converged</th><th scope=\"col\">Cap</th></tr></thead>" +
    "<tbody>" + rows.join("") + "</tbody></table>" +
    '<p class="hint">Global PageRank and PPR use tolerance ' + HW6_TOLERANCE + ", cap " + HW6_MAX_ITERATIONS +
    " iterations. The study example uses its own alpha and manual steps, with the same convergence tolerance. " +
    "Reaching the cap is not proof of convergence. PageRank is an iterative calculation, not neural-network training.</p>";
}

/**
 * Render the alpha sweep panel (readme section 6.1).
 *
 * @param {{rows:Array<Object>, best:(number|null), note:string}} [sweep]
 * @returns {void}
 */
function hw6RenderAlphaSweep(sweep) {
  const target = document.getElementById("alpha-sweep-results");
  if (!target) return;
  const data = sweep || { rows: HW6_STATE.alphaSweepRows, best: HW6_STATE.alphaSweepBest, note: HW6_STATE.alphaSweepNote || "" };
  if (!data || !data.rows || data.rows.length === 0) {
    target.innerHTML =
      '<p class="empty-state">Validation Recall@10 for alpha in {0.50, 0.70, 0.85, 0.95} is reported here; ' +
      "exact ties are broken by the smaller alpha.</p>";
    return;
  }
  const failed = data.rows.some(function (row) { return !!row.error; });
  if (failed) {
    const first = data.rows.find(function (row) { return !!row.error; });
    target.innerHTML = hw6UnavailableHtml("Alpha sweep", first.error);
    return;
  }

 */
function graphRenderConvergence() {
  const target = document.getElementById("fixture-convergence-results");
  if (!target) return;
  const fixture = GRAPH_VIEW_STATE.fixture;
  const p = fixture.p || [];
  const values = p
    .map((value, i) => REFERENCE_GRAPH.nodeOrder[i] + " " + Number(value).toFixed(10))
    .join(", ");
  const residual = fixture.residual === null ? "-" : Number(fixture.residual).toExponential(3);

  target.innerHTML =
    "<p><strong>Fixture demo (4-node reference graph)</strong> - iteration " +
    fixture.iteration +
    ", alpha " +
    Number(fixture.alpha !== undefined ? fixture.alpha : graphReadAlpha()).toFixed(2) +
    ", restart " +
    graphEscape(fixture.restart || "uniform") +
    ".</p>" +
    '<dl class="summary-list">' +
    "<dt>L1 residual (last step)</dt><dd>" + graphEscape(residual) + "</dd>" +
    "<dt>Current p</dt><dd>" + graphEscape(values) + "</dd>" +
    "</dl>" +
    '<p class="hint">This plain-JavaScript demo exists only for the 4-node fixture and is not a ' +
    "template for the MovieLens implementation, which must use TensorFlow.js tensor operations " +
    "on R and R-transpose (readme.md section 3.5).</p>";
  if (typeof hw6RenderConvergence === "function") hw6RenderConvergence();
}

/**
 * Advance the 4-node fixture demo by one propagation step and redraw it.
 *
 * @returns {void}
 */
function fixtureStep() {
  const fixture = GRAPH_VIEW_STATE.fixture;
  const alpha = graphReadAlpha();
  if (!fixture.p) {
    fixture.p = graphFixtureRestartVector(fixture.restart || "uniform");
    fixture.iteration = 0;
  }
  const result = graphFixturePropagate(alpha, fixture.restart || "uniform", fixture.p);
  fixture.p = result.p;
  fixture.iteration += 1;
  fixture.residual = result.residual;
  fixture.alpha = alpha;
