/** Switch workspaces without discarding recommendations or fixture progress. */
function hw6ShowWorkspace(tabId, focusTab) {
  document.querySelectorAll('[role="tab"][aria-controls]').forEach(tab => {
    const active = tab.id === tabId;
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = active ? 0 : -1;
    const panel = document.getElementById(tab.getAttribute("aria-controls"));
    if (panel) panel.hidden = !active;
    if (active && focusTab) tab.focus();
  });
  if (typeof graphHideTooltip === "function") graphHideTooltip();
  if (typeof graphRedrawVisibleViews === "function") graphRedrawVisibleViews();
  const activeTab = document.getElementById(tabId);
  if (activeTab) {
    const panel = document.getElementById(activeTab.getAttribute("aria-controls"));
    const tabBar = activeTab.closest('[role="tablist"]');
    const top = panel.getBoundingClientRect().top + window.scrollY - tabBar.offsetHeight - 20;
    window.scrollTo({ top: Math.max(0, top) });
  }
}

/** Standard click and keyboard navigation for the two app workspaces. */
function hw6WireWorkspaceTabs() {
  const tabs = Array.from(document.querySelectorAll('[role="tab"][aria-controls]'));
  tabs.forEach((tab, index) => {
    tab.addEventListener("click", () => hw6ShowWorkspace(tab.id, false));
    tab.addEventListener("keydown", event => {
      let next;
      if (event.key === "ArrowRight") next = (index + 1) % tabs.length;
      else if (event.key === "ArrowLeft") next = (index + tabs.length - 1) % tabs.length;
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = tabs.length - 1;
      else return;
      event.preventDefault();
      hw6ShowWorkspace(tabs[next].id, true);
    });
  });
}

