function recommendTopK(method, userId, K, split) {
  const limit = K === undefined ? 10 : Math.floor(Number(K));
  const name = split === "val" ? "val" : "test";
  const uid = Number(userId);
  if (!["popularity", "pagerank", "ppr", "mf"].includes(method) || !Number.isFinite(limit) || limit <= 0 ||
      !HW6_STATE.pairsBySplit.train.has(uid)) return [];
  const excluded = hw6ExclusionSet(name, uid);
  const candidates = HW6_STATE.candidateIds;
  if (!candidates.some(id => !excluded.has(id))) return [];
  if (method === "mf" && !HW6_MF_MODEL) throw new Error("Train the MF reference before requesting MF recommendations.");
  const vector = hw6ScoreVector(method, uid, hw6ReadAlpha(), name);
  const ranked = [];
  for (let i = 0; i < vector.movieIds.length; i++) {
    const movieId = vector.movieIds[i];
    const score = vector.scores[i];
    if (!excluded.has(movieId) && Number.isFinite(score)) ranked.push({ movieId, score });
  }
  ranked.sort((a, b) => b.score - a.score || a.movieId - b.movieId);
  return ranked.slice(0, limit).map(({ movieId, score }) => {
    const movie = hw6MovieById(movieId);
    return { movieId, title: movie ? movie.title : "Movie #" + movieId,
      genres: movie ? movie.genres.slice() : [], score, popularity: hw6PopularityOf(movieId) };
  });
}

