        "<td>" + hw6EscapeHtml(genres) + "</td>" +
        '<td class="num">' + hw6Fmt(rec.score) + "</td>" +
        '<td class="num">' + hw6PopularityOf(rec.movieId) + "</td>" +
        "</tr>"
      );
    })
    .join("");

  const zeroScore = recs.some(function (rec) { return !(Number(rec.score) > 0); });

  target.innerHTML =
