function hw6MfBatchLoss(userFactors, itemFactors, userIds, movieIds, actual, globalMean, regularization) {
  return tf.tidy(function () {
    const users = tf.gather(userFactors, userIds);
    const items = tf.gather(itemFactors, movieIds);
    const predicted = users.mul(items).sum(1).add(globalMean);
    const mse = predicted.sub(actual).square().mean();
    const l2 = users.square().sum(1).add(items.square().sum(1)).mean().mul(regularization);
    return mse.add(l2);
  });
}

